import type { ApplicationUser } from './application-user-model';
import type { WorkGroup } from './work-group-model';

export const AuditStatusKeyToLabel = {
  'Draft': 'Draft',
  'Submitted': 'Submitted',
  'Archived': 'Archived'
} as const;
export type AuditStatusKey = keyof typeof AuditStatusKeyToLabel;

export interface Audit {
  /**
   * @displayName Audit ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Audit Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  auditName: string;
  /**
   * @displayName Completed By
   */
  completedBy?: Pick<ApplicationUser, 'id' | 'applicationUserName'>;
  /**
   * @displayName Completed By Identity Snapshot
   * @validationRule Required for create/update operations
   */
  completedByIdentitySnapshot: string;
  /**
   * @displayName Created By
   * @validationRule Required for create/update operations
   */
  createdBy: Pick<ApplicationUser, 'id' | 'applicationUserName'>;
  /**
   * @displayName Created Date
   * @validationRule Required for create/update operations
   */
  createdDate: string;
  /**
   * @displayName Is Compliant
   * @validationRule Required for create/update operations
   */
  isCompliant: boolean;
  /**
   * @displayName Modified By
   * @validationRule Required for create/update operations
   */
  modifiedBy: Pick<ApplicationUser, 'id' | 'applicationUserName'>;
  /**
   * @displayName Modified Date
   * @validationRule Required for create/update operations
   */
  modifiedDate: string;
  /**
   * @displayName Name Not Found
   * @validationRule Required for create/update operations
   */
  nameNotFound: boolean;
  /**
   * @displayName Status
   * @validationRule Required for create/update operations
   */
  statusKey: AuditStatusKey;
  /**
   * @displayName Submitted Date
   */
  submittedDate?: string;
  /**
   * @displayName Visit Date
   * @validationRule Required for create/update operations
   */
  visitDate: string;
  /**
   * @displayName Work Group
   * @validationRule Required for create/update operations
   */
  workGroup: Pick<WorkGroup, 'id' | 'workGroupName'>;
}

export const _Audit = 'Audit' as const;